// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _test(uint256 amt1, uint256 amt2, uint256 min) internal {
        amt1 = bound(amt1, 0, 1000000000000000000000000000000);
        amt2 = bound(amt2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt1 > 0 && amt2 > 0);
        try c.SetMinSum(min) {} catch { return; }
        try c.SetLogFile(address(0x99)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: amt1}() {} catch { return; }
        uint256 bal1;
        try c.balances(address(this)) returns (uint256 __r) { bal1 = __r; } catch { return; }
        try c.Deposit{value: amt2}() {} catch { return; }
        uint256 bal2;
        try c.balances(address(this)) returns (uint256 __r) { bal2 = __r; } catch { return; }
        assertTrue(bal1 == amt1 && bal2 == amt1 + amt2);
    }

    function testFuzz_test(uint256 amt1, uint256 amt2, uint256 min) public {
        _test(amt1, amt2, min);
    }

    receive() external payable {}
}
